package dev.jackteng.encore;
import dev.jackteng.encore.monitoring.*;
import dev.jackteng.encore.delivery.DeliverySettings;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.amqp.rabbit.core.*;
import org.springframework.core.env.Environment;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"ticket.monitoring.enabled=true","ticket.monitoring.initial-delay-ms=3600000","ticket.delivery.enabled=true","ticket.delivery.publisher-enabled=false","ticket.delivery.consumer-enabled=false","ticket.delivery.namespace=encore-monitor-tests","ticket.expiry.enabled=false","ticket.stock-recovery.enabled=false","ticket.stock-return-recovery.enabled=false","ticket.stock-return-discovery.enabled=false"})
@AutoConfigureMockMvc
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class MonitoringIntegrationTest {
 @Autowired JdbcTemplate db;@Autowired HeartbeatStore heartbeats;@Autowired MonitoringStore store;@Autowired MonitoringService service;@Autowired DependencyProbe probes;
 @Autowired StringRedisTemplate redis;@Autowired Environment env;@Autowired RabbitAdmin admin;@Autowired RabbitTemplate rabbit;@Autowired DeliverySettings delivery;@Autowired MockMvc mvc;@Autowired PlatformTransactionManager transactions;
 String manager="monitor-"+UUID.randomUUID(),viewer="monitor-view-"+UUID.randomUUID();Set<UUID> owned=new HashSet<>();
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));for(String name:List.of(manager,viewer))db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),name,"synthetic unused hash",name.equals(manager)?"MANAGER":"VIEWER");admin.initialize();}
 @AfterEach void cleanup(){for(var id:owned)db.update("DELETE FROM runtime_heartbeat WHERE boot_id=?",id);owned.clear();admin.purgeQueue(delivery.queue(),false);}
 UUID beat(String role){var id=UUID.randomUUID();owned.add(id);heartbeats.pulse(id,role,false);return id;}
 MonitoringStore.Role role(String name){return store.read(manager,"EMBEDDED").roles().stream().filter(r->r.role().equals(name)).findFirst().orElseThrow();}
 String business(){StringJoiner q=new StringJoiner(",","SELECT jsonb_build_array(",")::text");for(String t:List.of("stock_projection","outbox_publication","stock_recovery_job","stock_return_recovery_job","stock_return_discovery_policy","stock_return_discovery_source","stock_return_recovery_audit","stock_hold_ack"))q.add("(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]') FROM "+t+" x)");return db.queryForObject(q.toString(),String.class);}
 @Test void snapshotLeavesBusinessAndHeartbeatRowsUnchanged(){var before=business();var heart=db.queryForObject("SELECT jsonb_agg(to_jsonb(x) ORDER BY boot_id)::text FROM runtime_heartbeat x",String.class);var s=service.snapshot(manager);assertTrue(s.enabled());assertEquals("UP",s.redis());assertEquals("UP",s.broker().state());assertEquals(22,s.postgres().counts().size());assertTrue(s.postgres().counts().values().stream().allMatch(n->n>=0));assertEquals(before,business());assertEquals(heart,db.queryForObject("SELECT jsonb_agg(to_jsonb(x) ORDER BY boot_id)::text FROM runtime_heartbeat x",String.class));}
 @Test void currentWorkerPulseBecomesStaleUsingPostgresClock(){var before=role("WORKER");var id=beat("WORKER");assertEquals(before.recent()+1,role("WORKER").recent());db.update("UPDATE runtime_heartbeat SET first_seen=clock_timestamp()-interval '60 seconds',last_seen=clock_timestamp()-interval '16 seconds' WHERE boot_id=?",id);assertEquals(before.recent(),role("WORKER").recent());assertEquals(before.stale()+1,role("WORKER").stale());heartbeats.pulse(id,"WORKER",false);assertEquals(before.recent()+1,role("WORKER").recent());assertEquals(1,db.queryForObject("SELECT count(*) FROM runtime_heartbeat WHERE boot_id=?",Integer.class,id));}
 @Test void heartbeatRetentionIsBoundedAndDoesNotTouchBusiness(){var before=business();for(int i=0;i<105;i++){var id=UUID.randomUUID();owned.add(id);db.update("INSERT INTO runtime_heartbeat(boot_id,role,first_seen,last_seen) VALUES(?,'WORKER',clock_timestamp()-interval '3 days',clock_timestamp()-interval '2 days')",id);}beat("WORKER");assertEquals(5,db.queryForObject("SELECT count(*) FROM runtime_heartbeat WHERE last_seen<clock_timestamp()-interval '24 hours'",Integer.class));assertEquals(before,business());}
 @Test void apiHeartbeatCannotClaimConsumerAndCannotRewriteBootRole(){var id=beat("API");assertThrows(org.springframework.dao.DataAccessException.class,()->heartbeats.pulse(id,"API",true));heartbeats.pulse(id,"WORKER",true);assertEquals("API",db.queryForObject("SELECT role FROM runtime_heartbeat WHERE boot_id=?",String.class,id));assertEquals(false,db.queryForObject("SELECT consumer_running FROM runtime_heartbeat WHERE boot_id=?",Boolean.class,id));}
 @Test void passiveBrokerProbeDoesNotConsumeQueuedPayload()throws Exception{var confirm=new org.springframework.amqp.rabbit.connection.CorrelationData(UUID.randomUUID().toString());rabbit.convertAndSend(delivery.exchange(),"purchase","synthetic-monitor-only",confirm);assertTrue(confirm.getFuture().get(5,java.util.concurrent.TimeUnit.SECONDS).isAck());long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(3);while(admin.getQueueInfo(delivery.queue()).getMessageCount()!=1){assertTrue(System.nanoTime()<end,"Confirmed fixture must become observable");Thread.sleep(25);}long before=admin.getQueueInfo(delivery.queue()).getMessageCount();assertEquals(1,before);var result=probes.broker();assertEquals("UP",result.state());assertEquals(1,result.queues().get("main").ready());assertEquals(0,result.queues().get("main").consumers());assertEquals(before,(long)admin.getQueueInfo(delivery.queue()).getMessageCount());}
 @Test void missingBrokerQueuesAreNeverAutoDeclaredByProbe(){var missing=new DeliverySettings(true,false,false,"encore-monitor-missing",2000,15,5000,3,4);var probe=new DependencyProbe(redis,missing,env);assertEquals("MISSING",probe.broker().state());assertNull(admin.getQueueInfo(missing.queue()));}
 @Test void aggregateRequiresCurrentStaffAndReadonlyRoutePermissions()throws Exception{assertEquals(403,assertThrows(Problem.class,()->service.snapshot("not-current-staff")).status);mvc.perform(get("/api/admin/monitoring")).andExpect(status().isUnauthorized());mvc.perform(get("/api/admin/monitoring").with(SecurityMockMvcRequestPostProcessors.user(viewer).authorities(()->"CATALOG_READ",()->"CATALOG_VIEW"))).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store")).andExpect(jsonPath("$.enabled").value(true));mvc.perform(post("/api/admin/monitoring").with(SecurityMockMvcRequestPostProcessors.user(manager).authorities(()->"CATALOG_READ",()->"CATALOG_WRITE")).with(SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().isMethodNotAllowed());}
 @Test void probesRejectOuterBusinessTransaction(){var before=business();assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactions).execute(tx->service.snapshot(manager)));assertEquals(before,business());}
 @Test void unavailablePgSnapshotReturnsSafe503WithoutDependencySideEffects(){db.execute("ALTER TABLE runtime_heartbeat RENAME TO monitor_test_unavailable");try{var p=assertThrows(Problem.class,()->service.snapshot(manager));assertEquals(503,p.status);assertEquals("MONITORING_UNAVAILABLE",p.code);assertFalse(p.getMessage().contains("runtime_heartbeat"));}finally{db.execute("ALTER TABLE monitor_test_unavailable RENAME TO runtime_heartbeat");}}
 @Test void disabledStoreDoesNotInferEmptyBacklogAndBoundsAreEnforced(){var settings=new MonitoringSettings(false,15,3000,2,2);var off=new MonitoringStore(db,settings);var tx=new TransactionTemplate(transactions);tx.setReadOnly(true);var data=tx.execute(t->off.read(viewer,"EMBEDDED"));assertTrue(data.roles().isEmpty());assertTrue(data.counts().isEmpty());assertThrows(IllegalArgumentException.class,()->new MonitoringSettings(true,5,3000,2,2));assertThrows(IllegalArgumentException.class,()->new MonitoringSettings(true,15,3000,17,2));assertThrows(IllegalArgumentException.class,()->new MonitoringSettings(true,15,3000,2,0));}
}
